Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Ltac zto pc := repeat (lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 pc) _ _ _ _) => fail | _ => zstep end).

Section CANSEC1. Context {rc : runConstT}.
Section X4F2.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m0 : fmem).
  Variables (DST dcap SS DT lo : Z) (src : list Z) (cells : list deltX1) (cbs : list byte).
  Notation SP := (bv_unsigned sp).
  Notation n := (zlen src).
  Hypothesis TOK : x1_table_ok cells 11.
  Hypothesis ECB : cbs = firstn 4096 (x1_bytes' cells).
  Hypothesis LCB : zlen cbs = 4096.
  Hypothesis D8 : 8 <= DST.
  Hypothesis DC : 0 < dcap < 2^32.
  Hypothesis DL : DST + dcap <= lo.
  Hypothesis S0 : 16 <= SS.
  Hypothesis SL : SS + n <= lo.
  Hypothesis NSM : n < 2^26.
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis DT0 : 0 < DT.
  Hypothesis CBL : DT + 4 + 4096 <= lo.
  Hypothesis DJ1 : DT + 4 + 4096 <= DST \/ DST + dcap <= DT.
  Hypothesis DJ3 : DST + dcap <= SS \/ SS + n <= DST.
  Hypothesis LOS : lo <= SP - 4096.
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis SP47 : SP <= 2^47.

  Notation DW := [(SP - 4096, SP); (DST, DST + dcap)].
  Notation POST := (huf_dec_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc DST dcap lo m0).
  Notation FRS := [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

  Notation X4M := (RF_huf_x4fin.X4M ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT lo src cbs).
  Notation XF l := (l ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 DST dcap SS DT lo src cells cbs
                     TOK ECB LCB D8 DC DL S0 SL NSM BYS DT0 CBL DJ1 DJ3 LOS SP16 SP47) (only parsing).

  Ltac x4pack OUT LB :=
    split; [eexists; split; [exact OUT| rewrite ?Zupd_length; exact LB]|];
    split; [eassumption|]; split; [eassumption|]; split; [eassumption|];
    split; [eexists; eassumption|];
    repeat (split; [eassumption|]); eassumption.

  Section STREAM.
  Variables (k SE OPk SEG DBC : Z) (sps ws : list word).
  Hypothesis K4 : 0 <= k < 4.
  Hypothesis HSE : DST <= OPk <= SE.
  Hypothesis HSE2 : SE <= DST + dcap.
  Hypothesis WOP : nth_error ws (Z.to_nat (4 + k)) = Some (Z_to_bv 64 OPk).
  Notation ST pc mm t6w a1 a2 a3 x9 x18 x19 x20 x21 x24 x25 x26 :=
    (MS (mkR (Z_to_bv 64 DST) (Z_to_bv 64 (SP + -416)) gp tp (Z_to_bv 64 SEG) (Z_to_bv 64 (SP + -256)) (Z_to_bv 64 4)
             (Z_to_bv 64 (SE - OPk)) x9 (Z_to_bv 64 (DT + 4)) a1 a2 a3 (Z_to_bv 64 66832) (Z_to_bv 64 k)
             (Z_to_bv 64 (SP + -136)) (Z_to_bv 64 DBC) x18 x19 x20 x21 (Z_to_bv 64 SS) (Z_to_bv 64 (SS + 8)) x24 x25 x26
             (Z_to_bv 64 dcap) (Z_to_bv 64 64) (Z_to_bv 64 SE) (Z_to_bv 64 (SP + -224 + 8 * k)) t6w)
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).
  Hypothesis CONT : forall mm (a1 a2 a3 x9 x18 x19 x20 x21 x24 x25 x26 : word),
    X4M mm sps ws -> evt psegs POST (ST 0x19094 mm (Z_to_bv 64 OPk) a1 a2 a3 x9 x18 x19 x20 x21 x24 x25 x26).
  Notation XS l := (XF l k SE OPk SEG DBC sps ws K4 HSE HSE2 WOP CONT) (only parsing).

  (* [comment removed for export] *)
  Lemma x4f_else : forall pt bits mm (a1 a2 a3 x18 x19 x20 x24 x25 x26 : word),
    X4M mm sps ws -> 0 <= pt -> pt + 8 <= n -> 0 <= bits <= 64 ->
    evt psegs POST (ST 0x18f50 mm (Z_to_bv 64 OPk) a1 a2 a3 (Z_to_bv 64 (SS + pt)) x18 x19 x20 (Z_to_bv 64 bits) x24 x25 x26).
